import {
  Group,
  Mesh,
  PlaneGeometry,
  Color,
  Box3,
  PointLight,
} from 'three/webgpu';
import { MeshBasicNodeMaterial, MeshStandardNodeMaterial } from 'three/webgpu';
import { uv, mix, color, fract, sin, dot, vec2 } from 'three/tsl';
import { gsap } from 'gsap';

export default function createNode(config, ctx) {
  const group = new Group();
  group.userData.handlers = {};

  // ---------- bridging / fallbacks ----------
  const colors = config.colors ?? config.intent?.visualSpec?.colors ?? {
    background: '#0b0b10',
    surface: '#101017',
    ink: '#16161d',
    paper: '#e8ecf2',
    accent: '#ff2a38',
    gradientStops: [{ at: 0, hex: '#0b0b10' }, { at: 1, hex: '#13131a' }],
  };

  const typography = config.typography ?? config.intent?.visualSpec?.typography ?? {
    hero: { family: 'Lora', fontSize: 124, fontWeight: 600, letterSpacing: -0.01 },
    subhead: { family: 'JetBrains Mono', fontSize: 40, fontWeight: 400, letterSpacing: 0.02 },
    caption: { family: 'JetBrains Mono', fontSize: 18, fontWeight: 700, letterSpacing: 0.12 },
  };

  const items = config.textContent ?? config.intent?.visualSpec?.textContent ?? [
    { text: 'NOVA ATELIER / CALIBRE PROGRAM', role: 'caption' },
    { text: 'TIME, MACHINED.', role: 'hero' },
    { text: 'Every calibre begins as a solid billet.', role: 'subhead' },
  ];

  const captionItem = items.find((i) => i.role === 'caption') ?? items[0];
  const heroItem = items.find((i) => i.role === 'hero') ?? items[1];
  const subheadItem = items.find((i) => i.role === 'subhead') ?? items[2];

  const letterSpacingPx = (fontSize, em) => fontSize * (em ?? 0);

  const disposables = [];

  // ---------- backdrop ----------
  const backdropGeo = new PlaneGeometry(7, 5.5);
  const backdropMat = new MeshBasicNodeMaterial();
  const stopBottom = color(colors.gradientStops?.[0]?.hex ?? colors.background);
  const stopTop = color(colors.gradientStops?.[1]?.hex ?? colors.surface);
  const gradient = mix(stopBottom, stopTop, uv().y);
  const grainSeed = dot(uv(), vec2(12.9898, 78.233));
  const grain = fract(sin(grainSeed).mul(43758.5453)).sub(0.5).mul(0.015);
  backdropMat.colorNode = gradient.add(grain);
  const backdrop = new Mesh(backdropGeo, backdropMat);
  backdrop.position.set(0, 0, -1.5);
  group.add(backdrop);
  disposables.push(() => { backdropGeo.dispose(); backdropMat.dispose(); });

  // ---------- rim / accent light (node-local, scene supplies ambient+key) ----------
  const rimLight = new PointLight(new Color(colors.accent), 0.8, 12, 2);
  rimLight.position.set(2.2, -1.0, 1.6);
  group.add(rimLight);

  // ---------- caption kicker ----------
  const capFontSize = captionItem.typography?.fontSize ?? typography.caption.fontSize ?? 18;
  const captionObj = ctx.fontAtlas.createText((captionItem.text ?? '').toUpperCase(), {
    fontSize: capFontSize,
    color: colors.paper,
    align: 'center',
    letterSpacingPx: letterSpacingPx(capFontSize, typography.caption.letterSpacing ?? 0.12),
  });
  captionObj.position.set(0, 1.15, 0);
  group.add(captionObj);

  // ---------- hero: per-word planes with front-to-back z offsets ----------
  const heroFontSize = heroItem.typography?.fontSize ?? typography.hero.fontSize ?? 124;
  const heroGroup = new Group();
  heroGroup.position.set(0, 0.4, 0);
  const words = (heroItem.text ?? 'TIME, MACHINED.').split(' ');
  const zOffsets = [0.12, 0.0, -0.12];
  let cursorX = 0;
  const wordMeshes = [];
  words.forEach((w, i) => {
    const label = i < words.length - 1 ? `${w} ` : w;
    const wordObj = ctx.fontAtlas.createText(label, {
      fontSize: heroFontSize,
      color: colors.paper,
      align: 'left',
      letterSpacingPx: letterSpacingPx(heroFontSize, typography.hero.letterSpacing ?? -0.01),
    });
    const box = new Box3().setFromObject(wordObj);
    const width = Math.max(box.max.x - box.min.x, 0.05);
    wordObj.position.x = cursorX;
    wordObj.position.z = zOffsets[i % zOffsets.length];
    heroGroup.add(wordObj);
    wordMeshes.push(wordObj);
    cursorX += width;
  });
  const totalWidth = cursorX;
  wordMeshes.forEach((w) => { w.position.x -= totalWidth / 2; });
  heroGroup.scale.set(1.04, 1.04, 1.04);
  group.add(heroGroup);

  // ---------- accent underline rule ----------
  const underlineGeo = new PlaneGeometry(2.6, 0.045);
  underlineGeo.translate(1.3, 0, 0);
  const underlineMat = new MeshStandardNodeMaterial();
  underlineMat.color = new Color(colors.accent);
  underlineMat.emissive = new Color(colors.accent);
  underlineMat.emissiveIntensity = 1.2;
  underlineMat.roughness = 0.5;
  underlineMat.metalness = 0.3;
  const underlineMesh = new Mesh(underlineGeo, underlineMat);
  const underlineGroup = new Group();
  underlineGroup.position.set(-1.3, -0.05, 0.05);
  underlineGroup.scale.x = 0.0001;
  underlineGroup.add(underlineMesh);
  group.add(underlineGroup);
  disposables.push(() => { underlineGeo.dispose(); underlineMat.dispose(); });

  // ---------- subhead ----------
  const subFontSize = subheadItem.typography?.fontSize ?? typography.subhead.fontSize ?? 40;
  const subheadObj = ctx.fontAtlas.createText(subheadItem.text ?? '', {
    fontSize: subFontSize,
    color: colors.paper,
    align: 'center',
    letterSpacingPx: letterSpacingPx(subFontSize, typography.subhead.letterSpacing ?? 0.02),
  });
  const subheadBaseY = -0.65;
  subheadObj.position.set(0, subheadBaseY + 0.2, 0);
  group.add(subheadObj);

  const setOpacity = (obj, val) => {
    obj.traverse((child) => {
      if (child.material) {
        child.material.transparent = true;
        child.material.opacity = val;
      }
    });
  };
  setOpacity(subheadObj, 0);
  setOpacity(captionObj, 0);
  captionObj.position.y = 0.95;

  // ---------- cinematic primitive: kinetic-text ----------
  const primitiveConfig = (config.cinematicPrimitives ?? []).find((p) => p.name === 'kinetic-text');
  const kineticParams = primitiveConfig?.params ?? { staggerMs: 60, riseUnits: 0.35 };
  const kineticResult = ctx.primitives['kinetic-text'](heroGroup, kineticParams);

  // ---------- gsap choreography for supporting elements ----------
  const glyphCount = Math.max((heroItem.text ?? '').length, 1);
  const glyphDurationS = 0.7;
  const staggerS = (kineticParams.staggerMs ?? 60) / 1000;
  const lastGlyphDelay = staggerS * (glyphCount - 1) + glyphDurationS;
  const underlineDelay = lastGlyphDelay + 0.12;

  const tl = gsap.timeline();

  tl.to(captionObj.position, { y: 1.15, duration: 0.5, ease: 'power2.out' }, 0);
  tl.to({ v: 0 }, {
    v: 1, duration: 0.5, ease: 'power2.out',
    onUpdate: function () { setOpacity(captionObj, this.targets()[0].v); },
  }, 0);

  tl.to(heroGroup.scale, { x: 1, y: 1, z: 1, duration: 0.9, ease: 'power4.out' }, lastGlyphDelay);

  tl.to(underlineGroup.scale, { x: 1, duration: 0.5, ease: 'power2.out' }, underlineDelay);

  tl.to(subheadObj.position, { y: subheadBaseY, duration: 0.5, ease: 'power2.out' }, underlineDelay);
  tl.to({ v: 0 }, {
    v: 1, duration: 0.5, ease: 'power2.out',
    onUpdate: function () { setOpacity(subheadObj, this.targets()[0].v); },
  }, underlineDelay);

  // ---------- cleanup ----------
  group.userData.cleanup = () => {
    tl.kill();
    kineticResult?.cleanup?.();
    disposables.forEach((fn) => fn());
    group.traverse((child) => {
      if (child.geometry) child.geometry.dispose?.();
      if (child.material) {
        if (Array.isArray(child.material)) child.material.forEach((m) => m.dispose?.());
        else child.material.dispose?.();
      }
    });
  };

  return group;
}
